import AppKit
import ImageIO
import os
import SwiftUI

/// Rookery's logo at the top of the sidebar: its crows in their nest beside the name, as animated pixel art
/// drawn one logo pixel to a point, never smoothed. The frames are generated by `branding/` into the app's
/// resources; Core Animation plays them in the render server, so the app does no work while they loop, and
/// they hold still under Reduce Motion. A build without them shows the name in text.
struct RookeryLogo: View {
    private static let name = "Rookery"
    private static let fallbackFontSize: CGFloat = 15

    var body: some View {
        if let timeline = SidebarLogoArt.timeline {
            RookeryLogoLayer(timeline: timeline)
                .frame(width: CGFloat(timeline.frameWidth), height: CGFloat(timeline.frameHeight))
                .accessibilityElement()
                .accessibilityLabel(Self.name)
        } else {
            Text(Self.name)
                .font(.system(size: Self.fallbackFontSize, weight: .bold))
        }
    }
}

/// How the sidebar logo's frames play, as `branding/` writes it beside them: each frame's size in pixels,
/// the frame rate, and which frame shows at each step of the loop.
struct SidebarLogoTimeline: Decodable, Equatable {
    let frameWidth: Int
    let frameHeight: Int
    let framesPerSecond: Double
    let listSequence: [Int]

    enum CodingKeys: String, CodingKey {
        case frameWidth = "frame_width"
        case frameHeight = "frame_height"
        case framesPerSecond = "frames_per_second"
        case listSequence = "sequence"
    }
}

/// The sidebar logo's art in the app's resources: the timeline, and the frames cut from the strip they are
/// laid out in, for a screen scale. Each is read once and kept.
@MainActor
enum SidebarLogoArt {
    private static let logger = Logger(subsystem: "io.github.zobinhuang.rookery", category: "stage")
    private static let resourceName = "SidebarLogo"
    private static var cachedTimeline: SidebarLogoTimeline??
    private static var mapFrames: [Int: [CGImage]] = [:]

    /// The timeline, or nil when the resources are missing or cannot be read.
    static var timeline: SidebarLogoTimeline? {
        if let cachedTimeline {
            return cachedTimeline
        }
        let timeline = readTimeline()
        cachedTimeline = .some(timeline)
        return timeline
    }

    /// The distinct frames for a screen scale, drawn from the strip made for it.
    ///
    /// - Parameter scale: the screen's backing scale, 1 or 2
    /// - Returns: the frames, or none when the strip cannot be read
    static func frames(scale: Int) -> [CGImage] {
        if let frames = mapFrames[scale] {
            return frames
        }
        let frames = readFrames(scale: scale)
        mapFrames[scale] = frames
        return frames
    }

    private static func readTimeline() -> SidebarLogoTimeline? {
        guard let url = Bundle.main.url(forResource: resourceName, withExtension: "json") else {
            return nil
        }
        do {
            return try JSONDecoder().decode(SidebarLogoTimeline.self, from: Data(contentsOf: url))
        } catch {
            logger.error("cannot read the sidebar logo's timeline: \(error)")
            return nil
        }
    }

    private static func readFrames(scale: Int) -> [CGImage] {
        let name = scale > 1 ? "\(resourceName)@\(scale)x" : resourceName
        guard
            let timeline,
            let url = Bundle.main.url(forResource: name, withExtension: "png"),
            let source = CGImageSourceCreateWithURL(url as CFURL, nil),
            let strip = CGImageSourceCreateImageAtIndex(source, 0, nil)
        else {
            logger.error("cannot read the sidebar logo's frames at \(scale)x")
            return []
        }
        let frameWidth = timeline.frameWidth * scale
        let frameHeight = timeline.frameHeight * scale
        return (0..<(strip.width / max(frameWidth, 1))).compactMap { frameIndex in
            strip.cropping(to: CGRect(x: frameIndex * frameWidth, y: 0, width: frameWidth, height: frameHeight))
        }
    }
}

/// The layer that plays the sidebar logo's frames.
struct RookeryLogoLayer: NSViewRepresentable {
    let timeline: SidebarLogoTimeline

    func makeNSView(context: Context) -> RookeryLogoView {
        RookeryLogoView(timeline: timeline)
    }

    func updateNSView(_ nsView: RookeryLogoView, context: Context) {}
}

/// The view behind `RookeryLogoLayer`: one layer whose contents a discrete keyframe animation steps
/// through, set up again whenever the view lands in a window or on a screen of another scale.
final class RookeryLogoView: NSView {
    private static let animationKey = "frames"
    private static let retinaScale = 2

    private let timeline: SidebarLogoTimeline
    private let frameLayer = CALayer()

    init(timeline: SidebarLogoTimeline) {
        self.timeline = timeline
        super.init(frame: .zero)
        wantsLayer = true
        frameLayer.magnificationFilter = .nearest
        frameLayer.minificationFilter = .nearest
        layer?.addSublayer(frameLayer)
    }

    required init?(coder: NSCoder) {
        nil
    }

    override func hitTest(_ point: NSPoint) -> NSView? {
        nil
    }

    override func layout() {
        super.layout()
        frameLayer.frame = bounds
    }

    override func viewDidMoveToWindow() {
        super.viewDidMoveToWindow()
        play()
    }

    override func viewDidChangeBackingProperties() {
        super.viewDidChangeBackingProperties()
        play()
    }

    /// Show the frames drawn for this screen's scale, looping them unless Reduce Motion is on.
    private func play() {
        guard let window else {
            frameLayer.removeAnimation(forKey: Self.animationKey)
            return
        }
        let scale = window.backingScaleFactor > 1 ? Self.retinaScale : 1
        let listFrames = SidebarLogoArt.frames(scale: scale)
        let listShown = timeline.listSequence.compactMap { listFrames.indices.contains($0) ? listFrames[$0] : nil }
        CATransaction.begin()
        CATransaction.setDisableActions(true)
        frameLayer.contentsScale = CGFloat(scale)
        frameLayer.contents = listShown.first
        CATransaction.commit()
        frameLayer.removeAnimation(forKey: Self.animationKey)
        guard
            listShown.count > 1,
            timeline.framesPerSecond > 0,
            !NSWorkspace.shared.accessibilityDisplayShouldReduceMotion
        else {
            return
        }
        let animation = CAKeyframeAnimation(keyPath: "contents")
        animation.values = listShown
        animation.calculationMode = .discrete
        animation.keyTimes = (0...listShown.count).map { NSNumber(value: Double($0) / Double(listShown.count)) }
        animation.duration = Double(listShown.count) / timeline.framesPerSecond
        animation.repeatCount = .infinity
        frameLayer.add(animation, forKey: Self.animationKey)
    }
}
